// Lift a colour toward white until it reads on `bg` (>= min:1).
function pbLift(t, hex, bg, min) {
  let c = hex;
  for (let k = 1; k <= 20 && t.contrast(c, bg) < min; k++) c = t.mix('#ffffff', hex, Math.min(1, k * 0.05));
  return c;
}

// Screen-side palette shared by tokens() and art(): the CRT black (a dark tint of the
// brand dark), the screen foreground, and the three brand colours lifted to read on it.
function pbScreen(t) {
  const d = t.isDark;
  const screen = d ? t.canvas : t.mix('#000000', t.ink, 0.55);
  const fg = d ? t.ink : '#ECECE6';
  return {
    screen, fg,
    dim: t.mix(fg, screen, 0.64),
    pri: pbLift(t, t.primary, screen, 4.5),
    sec: pbLift(t, t.secondary, screen, 4.5),
    acc: pbLift(t, t.accent, screen, 3),
  };
}

